//! Only original source rotary10 images/11functions/12 full ABI records.
use super::{CubinKernelManifest, VerifiedCubin, failure};
use cubecl_core::server::ServerError;
pub(super) fn require(image: &VerifiedCubin, m: &CubinKernelManifest) -> Result<(), ServerError> {
    if image.derived_from().is_some() || image.captured_from().is_none() {
        return Err(failure("rotary exact captured resource provenance"));
    }
    image
        .captured_from()
        .ok_or_else(|| failure("rotary captured source absent"))?
        .require_image(image.byte_len(), image.sha256(), image.binary_sm())?;
    require_record(image.sha256(), image.byte_len(), image.binary_sm(), m)
}
fn require_record(
    sha: [u8; 32],
    bytes: usize,
    sm: u8,
    m: &CubinKernelManifest,
) -> Result<(), ServerError> {
    let actual = super::attention_policy::digest(m);
    if !RULES
        .iter()
        .any(|r| r.0 == sha && r.1 == bytes && r.2 == sm && r.3 == actual)
    {
        return Err(failure(
            "source rotary complete image/geometry/scalar/stride/pointer/access ABI",
        ));
    }
    Ok(())
}
