#[cfg(test)]
mod tests {
    use super::super::CubinSetPolicy;
    #[test]
    fn rotary_capacity_is_closed_and_does_not_upgrade_existing_sets() {
        let p = CubinSetPolicy::SourceRotary;
        assert!(p.limits(9, 10, 11, true, true).is_ok());
        for v in [
            (10, 10, 11, true, false),
            (9, 11, 11, false, true),
            (9, 10, 12, false, false),
            (11, 0, 0, false, false),
        ] {
            assert!(p.limits(v.0, v.1, v.2, v.3, v.4).is_err());
        }
        for p in [
            CubinSetPolicy::ProjectionSix,
            CubinSetPolicy::ConnectedQwen08,
            CubinSetPolicy::FirstAttentionCaptured,
            CubinSetPolicy::VocabularyHead,
        ] {
            assert!(p.limits(10, 11, 11, true, true).is_err());
        }
    }
}

